using System;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Collections.Generic;using System.Windows.Forms;using System.Windows.Media.Media3D;
namespace GearLab {
 public sealed partial class MechanismForm {
  void EditInCAD(){var selected=Selected;if(selected==null){WorkspaceHost.Navigate(this,"cad");return;}try{var part=Assembly.Parts.First(p=>p.Id==selected.Id);var source=selected.NativeProject==null?CADNativeBridge.FromLegacyPart(part):CADDocument.Parse(selected.NativeProject);if(selected.NativeProject!=null)CADNativeBridge.AppendMove(source,part.Placement);string id=selected.Id;new CADStudioForm(source,native=>Mutate(()=>{var target=Project.Find(id);if(target==null)throw new Exception("Деталь удалена. Откройте редактор повторно.");AssignNative(target,native);})).ShowWorkspace(this);}catch(Exception ex){MessageBox.Show(this,ex.Message,"CAD-редактор");}}
  void AssignNative(MechanismPart target,CADNative native){var pos=Project.Position(target);target.NativeProject=native.Project;target.NativeStep=native.Step;target.NativePreview=native.Preview;target.NativeVolume=native.Volume;target.NativeCentre=native.Center;target.NativeBaseX=pos[0];target.NativeBaseY=pos[1];target.NativeBaseZ=pos[2];target.NativeBaseAngle=target.Angle;target.MatchShaft=false;var doc=CADDocument.Parse(native.Project);var gear=doc.Features.LastOrDefault(f=>f.Kind=="gear");if(gear!=null){var parameters=native.Parameters??new Dictionary<string,double>();target.Teeth=(int)CADExpression.Evaluate(gear.Values["Teeth"],parameters);target.Module=CADExpression.Evaluate(gear.Values["Module"],parameters);target.PressureAngle=CADExpression.Evaluate(gear.Values["Pressure"],parameters);target.HelixAngle=gear.Values.ContainsKey("Helix")?CADExpression.Evaluate(gear.Values["Helix"],parameters):0;target.GearForm=gear.Values["Type"];if(target.GearForm=="internal"||target.GearForm=="rack")target.Kind="block";if(gear.Values.ContainsKey("Bore"))target.Bore=CADExpression.Evaluate(gear.Values["Bore"],parameters);}}
  void AddGearPreset(){var worker=new CADKernel();var shaft=Project.Shaft(Selected);using(var library=new CADGearLibrary(worker,async feature=>{try{var doc=new CADDocument{Name=feature.Name};doc.Features.Add(feature);var result=await Task.Factory.StartNew(()=>worker.Run(doc,"native"));var b=result.Bodies[0];b.ReadMesh();var native=new CADNative{Project=doc.Serialize(),Step=result.Step,Preview=CADMeshCodec.Encode(b.Display),Volume=b.Volume,Center=b.Center};string form=feature.Values["Type"];return Mutate(()=>{var p=Project.Add(new[]{"spur","helical","herringbone"}.Contains(form)?"gear":"block");p.Name=feature.Name;p.Length=b.Bounds[5]-b.Bounds[2];p.Diameter=Math.Max(b.Bounds[3]-b.Bounds[0],b.Bounds[4]-b.Bounds[1]);p.Teeth=(int)CADExpression.Evaluate(feature.Values["Teeth"],null);p.Module=CADExpression.Evaluate(feature.Values["Module"],null);p.PressureAngle=CADExpression.Evaluate(feature.Values["Pressure"],null);p.HelixAngle=feature.Values.ContainsKey("Helix")?CADExpression.Evaluate(feature.Values["Helix"],null):0;p.GearForm=form;p.Bore=feature.Values.ContainsKey("Bore")?CADExpression.Evaluate(feature.Values["Bore"],null):0;p.MatchShaft=false;AssignNative(p,native);if(shaft!=null&&p.Kind=="gear"&&p.Length<=Project.ShaftLength(shaft)&&p.Bore>=Project.ShaftDiameter(shaft,0)){p.ShaftId=shaft.Id;p.OffsetZ=0;}selectedId=p.Id;});}catch(Exception ex){MessageBox.Show(this,ex.GetBaseException().Message,"Шестерня не добавлена");return false;}}))library.ShowDialog(this);worker.Dispose();}
  bool NativeOnly(){if(Selected==null||Selected.NativeStep==null)return false;MessageBox.Show(this,"Деталь содержит точное CAD-тело. Используйте «CAD Studio: деталь» для отверстий, скруглений, фасок и эскизов.");return true;}
 }
 public static class MechanismNative {
  public static CadPart Part(MechanismProject project,MechanismPart p){var mesh=CADMeshCodec.Decode(p.NativePreview);var bounds=new[]{mesh.Points.Min(v=>v.X),mesh.Points.Max(v=>v.X),mesh.Points.Min(v=>v.Y),mesh.Points.Max(v=>v.Y),mesh.Points.Min(v=>v.Z),mesh.Points.Max(v=>v.Z)};var part=new CadPart(p.Id,p.Name,p.Kind=="gear"?"gear":p.Kind=="shaft"?"shaft":"housing",System.Drawing.Color.FromArgb(174,187,203)){NativeStep=p.NativeStep,NativeVolume=p.NativeVolume,NativeCentre=new Point3D(p.NativeCentre[0],p.NativeCentre[1],p.NativeCentre[2]),MeshOverride=mesh};part.Sections.Add(new CadSection(bounds[4],bounds[5],CadLoop.Polygon(new[]{new System.Drawing.PointF((float)bounds[0],(float)bounds[2]),new System.Drawing.PointF((float)bounds[1],(float)bounds[2]),new System.Drawing.PointF((float)bounds[1],(float)bounds[3]),new System.Drawing.PointF((float)bounds[0],(float)bounds[3])}),null));var pos=project.Position(p);part.Placement=PartMotion.Around((p.Angle-p.NativeBaseAngle)*Math.PI/180,new Point3D(p.NativeBaseX,p.NativeBaseY,0),new Point3D(pos[0],pos[1],0),pos[2]-p.NativeBaseZ);return part;}
 }
}
